const coffees={
 instant:{kicker:'EVERYDAY, ELEVATED',title:'Instant gratification.<br>Without the rush.',description:'Coffee that fits your day. Explore freeze-dried, agglomerated and spray-dried formats, with pure coffee and chicory blend options.',color:'#c5b79a',variants:{'Freeze-dried':'Pure instant coffee — 100% coffee.','Agglomerated':'Pure coffee, 60/40 and 70/30 coffee–chicory options.','Spray-dried':'Pure coffee, 60/40 and 70/30 coffee–chicory options.','Custom blend':'Tell us the coffee and chicory blend you have in mind.'}},
 flavoured:{kicker:'A TWIST ON YOUR EVERYDAY',title:'A familiar ritual.<br>An unexpected note.',description:'Explore Pulpoffe’s flavoured instant coffee range, from warming spices to bright fruit notes. Pick a flavour to discover your next cup.',color:'#c09c72',variants:{'Hazelnut':'Hazelnut flavoured instant coffee.','Caramel':'Caramel flavoured instant coffee.','Choco Orange':'Choco Orange flavoured instant coffee.','Cardamom':'Cardamom flavoured instant coffee.','Vanilla':'Vanilla flavoured instant coffee.','More flavours':'Also available: Spiced, Almond, Mint, Berry and custom flavours.'}},
 fermented:{kicker:'FOR THE CURIOUS CUP',title:'Let curiosity<br>do the brewing.',description:'Discover our fermented roasted bean coffee powder collection. A different expression of coffee, with four distinctive options to explore.',color:'#b9958c',variants:{'Whiskey barrel aged':'Whiskey barrel aged fermented roasted bean coffee powder — 100% coffee.','Pineapple':'Pineapple fermented roasted bean coffee powder — 100% coffee.','Cinnamon':'Cinnamon fermented roasted bean coffee powder — 100% coffee.','Wine':'Wine fermented roasted bean coffee powder — 100% coffee.'}},
 roasted:{kicker:'TAKE THE SLOW ROUTE',title:'Your ritual.<br>Fresh perspective.',description:'Explore roasted coffee powder and Arabica–Robusta blends with chicory. Choose pure coffee or find the balance that suits your cup.',color:'#ad9e7c',variants:{'Pure coffee':'Roasted bean coffee powder — 100% coffee.','60 / 40':'60% coffee and 40% chicory blend.','70 / 30':'70% coffee and 30% chicory blend.','80 / 20':'80% coffee and 20% chicory blend.','Custom blend':'A custom coffee blend, subject to confirmation.'}}
};
const $=s=>document.querySelector(s);
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
$('#year').textContent=new Date().getFullYear();
const menu=$('#menu-toggle');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));$('#mobile-menu').hidden=open;});
$('#mobile-menu').addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');$('#mobile-menu').hidden=true;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');$('#mobile-menu').hidden=true;}});
const dialog=$('#coffee-dialog');
let lastCoffeeTrigger;
document.querySelectorAll('[data-coffee]').forEach(b=>b.addEventListener('click',()=>{const type=b.dataset.coffee,c=coffees[type];lastCoffeeTrigger=b;$('#dialog-kicker').textContent=c.kicker;$('#dialog-title').innerHTML=c.title;$('#dialog-description').textContent=c.description;$('#dialog-image').src=`assets/${type}.webp`;$('#dialog-image').alt=`Illustrative ${type} coffee scene`;$('#dialog-variants').replaceChildren();Object.entries(c.variants).forEach(([name,detail])=>{const wrap=document.createElement('div'),strong=document.createElement('strong'),p=document.createElement('p');strong.textContent=name;p.textContent=detail;wrap.append(strong,p);$('#dialog-variants').append(wrap);});dialog.showModal();document.body.style.overflow='hidden';}));
function closeDialog(){dialog.close();document.body.style.overflow='';lastCoffeeTrigger?.focus();}
$('.dialog-close').addEventListener('click',closeDialog);dialog.addEventListener('cancel',()=>{document.body.style.overflow='';});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});$('#dialog-blend').addEventListener('click',closeDialog);
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on));});document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=b.dataset.filter!=='all'&&card.dataset.category!==b.dataset.filter;if(!card.hidden)card.classList.add('visible');});}));
const ratio=$('#ratio'),flavour=$('#flavour');
function blendUpdate(e){const format=new FormData($('#blend-form')).get('format');const instant=format==='Instant';if(!instant){flavour.value='Original / unflavoured';}if(e?.target===flavour&&flavour.selectedIndex>0)ratio.value=100;if(e?.target===ratio&&Number(ratio.value)<100)flavour.value='Original / unflavoured';flavour.disabled=!instant;$('#flavour-note').textContent=instant?'Flavoured instant coffees are listed as 100% coffee. Choosing a flavour sets the coffee ratio to 100%.':'Flavours in this selector apply to instant coffee. Choose your roasted coffee ratio above.';const n=Number(ratio.value);$('#ratio-output').textContent=`${n} / ${100-n}`;$('#blend-summary').textContent=`${format} · ${n}% coffee${n<100?` / ${100-n}% chicory`:''} · ${flavour.value}`;$('#download-status').textContent='';}
$('#blend-form').addEventListener('input',blendUpdate);$('#blend-form').addEventListener('change',blendUpdate);blendUpdate();
$('#blend-form').addEventListener('submit',e=>{e.preventDefault();const content=`PULPOFFE — MY BLEND BRIEF\n\n${$('#blend-summary').textContent}\n\nThis is a preference brief, not an order or submitted enquiry.\nCustom blends and flavour combinations are subject to confirmation by Pulpoffe.\n\nMoments brewed. Impacts grown.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Pulpoffe-my-blend-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#download-status').textContent='Your blend brief is ready. Check your downloads.';});
